-- Link finished products to matching BOMs/recipes (name match)
  company_id, product_id, recipe_id, recipe_name_snapshot, portion_qty, portion_cost
)
select distinct on (p.id)
  p.company_id,
  p.id,
  r.id,
  r.recipe_name,
  1.000,
  coalesce(r.total_cost, 0)
from public.vyron_cost_products p
inner join public.vyron_cost_recipes r
  on r.company_id = p.company_id
  and (
    lower(trim(r.recipe_name)) = lower(trim(p.product_name))
    or lower(trim(p.product_name)) like '%' || lower(trim(r.recipe_name)) || '%'
    or lower(trim(r.recipe_name)) like '%' || lower(trim(p.product_name)) || '%'
  )
where p.company_id = '48002864-8800-4000-9000-000000000001'
order by p.id, length(r.recipe_name) desc;

-- Recommended performance indexes
create index if not exists idx_vyron_cost_products_company_name on public.vyron_cost_products(company_id, lower(product_name));
create index if not exists idx_vyron_cost_ingredients_company_name on public.vyron_cost_ingredients(company_id, lower(ingredient_name));
create index if not exists idx_vyron_cost_lines_company_product on public.vyron_cost_product_cost_lines(company_id, lower(product_name));
create index if not exists idx_vyron_cost_recipes_company_name on public.vyron_cost_recipes(company_id, lower(recipe_name));
